async fn malformed_srt_is_atomic_and_engine_selection_is_canonical() {
 let r=setup().await;edit(&r,json!({"type":"setEngine","engine":"external"})).await;
 let before=state(&r).await;assert_eq!(before["project"]["classic"]["document"]["transcriptionEngine"],"external");
 for text in ["", "1\n00:60:00,000 --> 00:61:00,000\ninvalid", "1\n00:00:01,000 --> 00:00:00,500\nbackwards", "1\n00:00:01,000 --> 00:00:02,000\ngood\n\n2\ninvalid"] {
 let error=r.registry().invoke(CAP,InvocationContext::default(),json!({"projectId":"classic-project","expectedRevision":before["revision"],"jobId":"import-job","change":{"type":"importSrt","sceneId":"main-scene","text":text,"settings":{},"defaults":job(&before)["defaults"]}})).await;
 assert!(error.is_err());assert_eq!(state(&r).await,before);
 }
